const e = $('On workflow error').first().json;
const lead = $input.first().json;
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[ch]);
const title = `⚠️ Lead intake failed: ${e.workflow?.name ?? 'workflow'}`;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: `*${esc(e.execution?.lastNodeExecuted ?? 'unknown step')}:* ${esc(e.execution?.error?.message ?? 'unknown error')}` } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `${lead.id ? `Lead #${lead.id} marked as error; resubmitting it retries from the failed step.` : 'No lead row matched.'} ${e.execution?.url ? `<${e.execution.url}|Open execution>` : ''}` }] },
];
return [{ json: { text: title, blocks: JSON.stringify({ blocks }) } }];
